// Authenticated, allowlisted Gravity Forms form 1 normalizer.
// This workflow deliberately has no downstream connection. The normalized
// contract is retained in n8n execution data for verification only.
const crypto = require('crypto');
const envelope = $input.first().json || {};
const headers = envelope.headers && typeof envelope.headers === 'object'
  ? envelope.headers
  : {};
const supplied = String(
  Object.entries(headers).find(([key]) => key.toLowerCase() === 'x-cnpc-webhook-secret')?.[1] || '',
);

// SHA-256 digest of the separately managed Gravity Forms ingress secret. The
// secret itself is never stored in this workflow or forwarded downstream.
const expectedDigest = 'a170a77346b7af36b749ee9dbd1faf49dfeb4108b7fed2e86a0ba00217b2e1b1';
const suppliedDigest = crypto.createHash('sha256').update(supplied, 'utf8').digest('hex');
const authenticated = supplied.length > 0 && crypto.timingSafeEqual(
  Buffer.from(suppliedDigest, 'hex'),
  Buffer.from(expectedDigest, 'hex'),
);

const result = (statusCode, response, normalized) => [{
  json: { status_code: statusCode, response, ...(normalized ? { normalized } : {}) },
}];

if (!authenticated) {
  return result(401, { accepted: false, error: 'unauthorized' });
}

const body = envelope.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return result(422, { accepted: false, error: 'JSON object body required' });
}

const encodedLength = Buffer.byteLength(JSON.stringify(body), 'utf8');
if (encodedLength > 262144 || Object.keys(body).length > 300) {
  return result(413, { accepted: false, error: 'payload exceeds intake limits' });
}

const text = (key, maxLength) => {
  const value = body[key];
  if (value === undefined || value === null) return '';
  return String(value).trim().slice(0, maxLength);
};
const formId = text('form_id', 64);
const entryId = text('id', 64);
if (formId !== '1' || !/^\d{1,20}$/.test(entryId)) {
  return result(422, { accepted: false, error: 'unexpected Gravity Forms identity' });
}

const organizationTypes = {
  'Non-profit 501(c)3': 'nonprofit_501c3',
  'Not-for-profit other 501(c)': 'nonprofit_other_501c',
  'For profit': 'for_profit',
  'Not sure': 'unsure',
};
const expenseBands = {
  'Small (OpEx Budget under $250,000 USD / year)': 'under_250k',
  'Medium (OpEx Budget under $500,000 USD / year)': '250k_to_499999',
  'Large (OpEx Budget over $500,000 USD / year)': '500k_plus',
};
const coachingTypes = {
  Individual: 'individual',
  Team: 'team',
  Both: 'both',
  'Not Sure': 'unsure',
};

const organizationType = organizationTypes[text('21', 100)];
const expenseBand = expenseBands[text('22', 160)];
const coachingType = coachingTypes[text('24', 40)];
const required = {
  first_name: text('1.3', 100),
  last_name: text('1.6', 100),
  email: text('2', 320),
  lead_source: text('16', 500),
  organization_name: text('20', 500),
  website: text('17', 2048),
  city: text('4.3', 200),
  state: text('4.4', 100),
  why_coaching: text('3', 10000),
};
const missing = Object.entries(required)
  .filter(([, value]) => !value)
  .map(([key]) => key);
const consent = ['1', 'true', 'yes', 'on'].includes(text('29.1', 20).toLowerCase());
if (missing.length || !organizationType || !expenseBand || !coachingType || !consent) {
  return result(422, {
    accepted: false,
    error: 'required or enumerated field validation failed',
    missing_fields: missing,
    invalid_fields: [
      ...(!organizationType ? ['organization_type'] : []),
      ...(!expenseBand ? ['operating_expense_band'] : []),
      ...(!coachingType ? ['coaching_type'] : []),
      ...(!consent ? ['consent'] : []),
    ],
  });
}

const rawDate = text('date_created', 64);
let submittedAt = new Date().toISOString();
if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(rawDate)) {
  submittedAt = `${rawDate.replace(' ', 'T')}.000Z`;
} else if (rawDate && !Number.isNaN(Date.parse(rawDate))) {
  submittedAt = new Date(rawDate).toISOString();
}

const submissionId = `gf:${formId}:${entryId}`;
const normalized = {
  submission_id: submissionId,
  submitted_at: submittedAt,
  applicant: {
    first_name: required.first_name,
    last_name: required.last_name,
    email: required.email,
    lead_source: required.lead_source,
  },
  organization: {
    legal_name: required.organization_name,
    website: required.website,
    city: required.city,
    state: required.state,
    organization_type: organizationType,
    operating_expense_band: expenseBand,
  },
  request: {
    program_track: 'cnpc',
    coaching_type: coachingType,
    why_coaching: required.why_coaching,
    first_choice_coach: text('30', 500),
    second_choice_coach: text('31', 500),
    anything_else: text('28', 10000),
  },
  consent: true,
  source: { form_id: formId, entry_id: entryId },
};

return result(202, {
  accepted: true,
  capture_only: true,
  normalized: true,
  submission_id: submissionId,
  mapping_version: 'gf-form-1-v1',
}, normalized);
